const SESSION_ID: u64 = 123;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

struct Config {
    seed: u64,
    iters: u64,
    secs: u64,
    max_len: usize,
    only_case: Option<u64>,
    out_dir: PathBuf,
    slow: Duration,
    hang: Duration,
    huge_images: bool,
    in_flight: bool,
}

fn env_u64(name: &str) -> Option<u64> {
    std::env::var(name).ok().and_then(|v| v.trim().parse().ok())
}

fn env_flag(name: &str, default: bool) -> bool {
    match std::env::var(name) {
        Ok(v) => matches!(v.trim(), "1" | "true" | "yes" | "on"),
        Err(_) => default,
    }
}

fn default_out_dir() -> PathBuf {
    if let Ok(dir) = std::env::var("PHOSPHOR_FUZZ_OUT") {
        return PathBuf::from(dir);
    }
    if let Ok(dir) = std::env::var("CARGO_TARGET_DIR") {
        return PathBuf::from(dir).join("fuzz-cases");
    }
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("target")
        .join("fuzz-cases")
}

impl Config {
    fn from_env() -> Self {
        let seed = env_u64("PHOSPHOR_FUZZ_SEED").unwrap_or_else(|| {
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|d| d.as_nanos() as u64)
                .unwrap_or(0x5eed)
        });
        Config {
            seed,
            iters: match env_u64("PHOSPHOR_FUZZ_ITERS").unwrap_or(2000) {
                0 => u64::MAX,
                n => n,
            },
            secs: env_u64("PHOSPHOR_FUZZ_SECS").unwrap_or(60),
            max_len: env_u64("PHOSPHOR_FUZZ_MAX_LEN").unwrap_or(64 * 1024).max(1) as usize,
            only_case: env_u64("PHOSPHOR_FUZZ_CASE"),
            out_dir: default_out_dir(),
            slow: Duration::from_millis(env_u64("PHOSPHOR_FUZZ_SLOW_MS").unwrap_or(2000)),
            hang: Duration::from_secs(env_u64("PHOSPHOR_FUZZ_HANG_SECS").unwrap_or(60).max(1)),
            huge_images: env_flag("PHOSPHOR_FUZZ_HUGE_IMAGES", false),
            in_flight: env_flag("PHOSPHOR_FUZZ_IN_FLIGHT", true),
        }
    }
}

/// Derives the per-case RNG seed (splitmix64 over the master seed and index).
fn case_seed(seed: u64, index: u64) -> u64 {
    let mut z = seed ^ index.wrapping_add(1).wrapping_mul(0x9E37_79B9_7F4A_7C15);
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

// ---------------------------------------------------------------------------
// Case representation
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug)]
struct Flags {
    kitty_images: bool,
    osc_hyperlinks: bool,
    tmux_control_mode: bool,
}

/// One step of a case. `Feed` is one `Processor::parse_bytes` call (i.e. one
/// pty read); everything else is an operation on the model between reads.
#[derive(Clone, Debug)]
enum Op {
    Feed(Vec<u8>),
    Resize {
        rows: usize,
        cols: usize,
    },
    /// `Processor::finish_sync_output`, as the event loop does when a
    /// synchronized update times out.
    FinishSync,
    /// Drops all parser state, as `TerminalModel::process_bytes` does per call.
    ResetProcessor,
    /// `TerminalModel::start_command_execution` (user pressed enter).
    StartCommand,
    /// Direct `Handler` calls, bypassing the parser and session validation.
    Preexec(String),
    CommandFinished {
        exit: i32,
        block_id: String,
    },
    Precmd {
        exit: i32,
        block_id: String,
    },
    PromptOnlyPrecmd,
    ClearHook,
    ClearVisibleScreen,
    Find {
        query: String,
        regex: bool,
        case_sensitive: bool,
    },
    Check,
}

impl Op {
    fn summary(&self) -> String {
        match self {
            Op::Feed(bytes) => format!("feed {} bytes", bytes.len()),
            Op::Resize { rows, cols } => format!("resize {rows}x{cols}"),
            Op::FinishSync => "finish_sync".to_owned(),
            Op::ResetProcessor => "reset_processor".to_owned(),
            Op::StartCommand => "start_command".to_owned(),
            Op::Preexec(cmd) => format!("preexec {cmd:?}"),
            Op::CommandFinished { exit, block_id } => {
                format!("command_finished exit={exit} next={block_id:?}")
            }
            Op::Precmd { exit, block_id } => format!("precmd exit={exit} next={block_id:?}"),
            Op::PromptOnlyPrecmd => "prompt_only_precmd".to_owned(),
            Op::ClearHook => "clear_hook".to_owned(),
            Op::ClearVisibleScreen => "clear_visible_screen".to_owned(),
            Op::Find {
                query,
                regex,
                case_sensitive,
            } => format!("find {query:?} regex={regex} case_sensitive={case_sensitive}"),
            Op::Check => "check".to_owned(),
        }
    }
}

struct Case {
    seed: u64,
    index: u64,
    flags: Flags,
    ops: Vec<Op>,
    /// `(offset, len, kind)` of each generated fragment within the concatenated
    /// stream; descriptive only (written as comments in the `.ops` file).
    fragments: Vec<(usize, usize, String)>,
}

impl Case {
    fn stream_len(&self) -> usize {
        self.ops
            .iter()
            .map(|op| match op {
                Op::Feed(bytes) => bytes.len(),
                _ => 0,
            })
            .sum()
    }

    /// The concatenation of every `Feed`, i.e. the `.bin` file.
    fn stream(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.stream_len());
        for op in &self.ops {
            if let Op::Feed(bytes) = op {
                out.extend_from_slice(bytes);
            }
        }
        out
    }

    /// The `.ops` text format. `feed` lines refer to `<offset> <len>` in the
    /// `.bin`; strings are hex-encoded so any byte survives.
    fn ops_text(&self, header: &str) -> String {
        let mut out = String::new();
        let _ = writeln!(
            out,
            "# phosphor terminal fuzz case; replay with PHOSPHOR_FUZZ_REPLAY=<this file>"
        );
        for line in header.lines() {
            let _ = writeln!(out, "# {line}");
        }
        let _ = writeln!(out, "seed {}", self.seed);
        let _ = writeln!(out, "case {}", self.index);
        let _ = writeln!(
            out,
            "flags kitty_images={} osc_hyperlinks={} tmux_control_mode={}",
            self.flags.kitty_images as u8,
            self.flags.osc_hyperlinks as u8,
            self.flags.tmux_control_mode as u8
        );
        for (offset, len, kind) in &self.fragments {
            let _ = writeln!(out, "# fragment {offset} {len} {kind}");
        }
        let mut offset = 0;
        for op in &self.ops {
            let _ = match op {
                Op::Feed(bytes) => {
                    let line = writeln!(out, "feed {offset} {}", bytes.len());
                    offset += bytes.len();
                    line
                }
                Op::Resize { rows, cols } => writeln!(out, "resize {rows} {cols}"),
                Op::FinishSync => writeln!(out, "finish_sync"),
                Op::ResetProcessor => writeln!(out, "reset_processor"),
                Op::StartCommand => writeln!(out, "start_command"),
                Op::Preexec(cmd) => writeln!(out, "preexec {}", hex_or_dash(cmd)),
                Op::CommandFinished { exit, block_id } => {
                    writeln!(out, "command_finished {exit} {}", hex_or_dash(block_id))
                }
                Op::Precmd { exit, block_id } => {
                    writeln!(out, "precmd {exit} {}", hex_or_dash(block_id))
                }
                Op::PromptOnlyPrecmd => writeln!(out, "prompt_only_precmd"),
                Op::ClearHook => writeln!(out, "clear_hook"),
                Op::ClearVisibleScreen => writeln!(out, "clear_visible_screen"),
                Op::Find {
                    query,
                    regex,
                    case_sensitive,
                } => writeln!(
                    out,
                    "find {} {} {}",
                    *regex as u8,
                    *case_sensitive as u8,
                    hex_or_dash(query)
                ),
                Op::Check => writeln!(out, "check"),
            };
        }
        out
    }
}

fn hex_or_dash(s: &str) -> String {
    if s.is_empty() {
        "-".to_owned()
    } else {
        hex::encode(s)
    }
}

fn unhex_or_dash(s: &str) -> Result<String, String> {
    if s == "-" {
        return Ok(String::new());
    }
    hex::decode(s)
        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned())
        .map_err(|e| format!("bad hex {s:?}: {e}"))
}

/// Parses an `.ops` file written by [`Case::ops_text`] against its `.bin`.
fn parse_case(ops_text: &str, stream: &[u8]) -> Result<Case, String> {
    let mut case = Case {
        seed: 0,
        index: 0,
        flags: Flags {
            kitty_images: true,
            osc_hyperlinks: true,
            tmux_control_mode: false,
        },
        ops: vec![],
        fragments: vec![],
    };
    for (line_no, line) in ops_text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let err = |msg: &str| format!("line {}: {msg}: {line:?}", line_no + 1);
        let words: Vec<&str> = line.split_whitespace().collect();
        let num = |i: usize| -> Result<i64, String> {
            words
                .get(i)
                .and_then(|w| w.parse::<i64>().ok())
                .ok_or_else(|| err("expected a number"))
        };
        let word = |i: usize| words.get(i).copied().ok_or_else(|| err("missing field"));
        match words[0] {
            "seed" => case.seed = word(1)?.parse().map_err(|_| err("bad seed"))?,
            "case" => case.index = word(1)?.parse().map_err(|_| err("bad case"))?,
            "flags" => {
                for kv in &words[1..] {
                    let (key, value) = kv.split_once('=').ok_or_else(|| err("bad flag"))?;
                    let value = value == "1";
                    match key {
                        "kitty_images" => case.flags.kitty_images = value,
                        "osc_hyperlinks" => case.flags.osc_hyperlinks = value,
                        "tmux_control_mode" => case.flags.tmux_control_mode = value,
                        _ => return Err(err("unknown flag")),
                    }
                }
            }
            "feed" => {
                let offset = num(1)? as usize;
                let len = num(2)? as usize;
                let bytes = stream
                    .get(offset..offset.saturating_add(len))
                    .ok_or_else(|| err("feed range is outside the .bin"))?;
                case.ops.push(Op::Feed(bytes.to_vec()));
            }
            "resize" => case.ops.push(Op::Resize {
                rows: num(1)? as usize,
                cols: num(2)? as usize,
            }),
            "finish_sync" => case.ops.push(Op::FinishSync),
            "reset_processor" => case.ops.push(Op::ResetProcessor),
            "start_command" => case.ops.push(Op::StartCommand),
            "preexec" => case.ops.push(Op::Preexec(unhex_or_dash(word(1)?)?)),
            "command_finished" => case.ops.push(Op::CommandFinished {
                exit: num(1)? as i32,
                block_id: unhex_or_dash(word(2)?)?,
            }),
            "precmd" => case.ops.push(Op::Precmd {
                exit: num(1)? as i32,
                block_id: unhex_or_dash(word(2)?)?,
            }),
            "prompt_only_precmd" => case.ops.push(Op::PromptOnlyPrecmd),
            "clear_hook" => case.ops.push(Op::ClearHook),
            "clear_visible_screen" => case.ops.push(Op::ClearVisibleScreen),
            "find" => case.ops.push(Op::Find {
                regex: num(1)? != 0,
                case_sensitive: num(2)? != 0,
                query: unhex_or_dash(word(3)?)?,
            }),
            "check" => case.ops.push(Op::Check),
            _ => return Err(err("unknown op")),
        }
    }
    Ok(case)
}

