#[derive(Clone, Copy)]
enum ChunkMode {
    Whole,
    SingleByte,
    UpTo(usize),
}

struct Gen<'a> {
    rng: StdRng,
    cfg: &'a Config,
    flags: Flags,
    target_len: usize,
    chunk_mode: ChunkMode,
    pending: Vec<u8>,
    flushed: usize,
    ops: Vec<Op>,
    fragments: Vec<(usize, usize, String)>,
    block_ids: Vec<String>,
    next_block: u32,
}

