impl<'a> Gen<'a> {
    fn pick<T: Copy>(&mut self, items: &[T]) -> T {
        items[self.rng.gen_range(0..items.len())]
    }

    fn chance(&mut self, p: f64) -> bool {
        self.rng.gen_bool(p)
    }

    fn remaining(&self) -> usize {
        self.cfg
            .max_len
            .saturating_sub(self.flushed + self.pending.len())
    }

    fn num(&mut self) -> String {
        if self.chance(0.7) {
            self.pick(NUMS).to_owned()
        } else {
            self.rng.gen_range(0..=70_000u32).to_string()
        }
    }

    fn small_num(&mut self) -> String {
        if self.chance(0.8) {
            self.rng.gen_range(0..=300u32).to_string()
        } else {
            self.num()
        }
    }

    fn random_bytes(&mut self, len: usize) -> Vec<u8> {
        let mut bytes = vec![0u8; len];
        self.rng.fill(&mut bytes[..]);
        bytes
    }

    fn b64(&mut self, max: usize) -> String {
        let len = self.rng.gen_range(0..=max);
        let bytes = self.random_bytes(len);
        base64::engine::general_purpose::STANDARD.encode(bytes)
    }

    fn word_text(&mut self, words: usize) -> String {
        let mut s = String::new();
        for i in 0..words {
            if i > 0 {
                s.push(' ');
            }
            if self.chance(0.15) {
                s.push_str(self.pick(UNICODE));
            } else {
                s.push_str(self.pick(WORDS));
            }
        }
        s
    }

    fn terminator(&mut self) -> &'static [u8] {
        match self.rng.gen_range(0..100) {
            0..=44 => b"\x07",
            45..=84 => b"\x1b\\",
            85..=89 => b"\x9c",
            90..=94 => b"",
            _ => b"\x1b",
        }
    }

    fn new_block_id(&mut self) -> String {
        let roll = self.rng.gen_range(0..100);
        if roll < 15 && !self.block_ids.is_empty() {
            let i = self.rng.gen_range(0..self.block_ids.len());
            return self.block_ids[i].clone();
        }
        if roll < 20 {
            return String::new();
        }
        if roll < 25 {
            return format!("\u{1f44d};{}\u{0}", "x".repeat(self.rng.gen_range(0..2000)));
        }
        self.next_block += 1;
        let id = format!("fuzz-{}", self.next_block);
        self.block_ids.push(id.clone());
        id
    }

    fn exit_code(&mut self) -> i32 {
        self.pick(&[0, 0, 0, 1, 2, 127, 130, 255, -1, i32::MAX, i32::MIN])
    }

    // -- fragments --------------------------------------------------------

    fn frag_raw(&mut self) -> Vec<u8> {
        let len = if self.chance(0.9) {
            self.rng.gen_range(1..=256)
        } else {
            self.rng.gen_range(256..=4096)
        };
        self.random_bytes(len)
    }

    /// Bytes drawn from the characters that drive parser state transitions.
    fn frag_escape_soup(&mut self) -> Vec<u8> {
        const SOUP: &[u8] = b"\x1b\x1b\x1b[[]]];;;:0123456789?>=<!$\"' P\\_^X\x07\x9c\x90\x9b\x9d\x98\x9e\x9fGqmhltdfk\x18\x1a\x00\x7f\r\n";
        let len = self.rng.gen_range(1..=512);
        (0..len).map(|_| self.pick(SOUP)).collect()
    }

    fn frag_text(&mut self) -> Vec<u8> {
        let lines = self.rng.gen_range(1..=8);
        let mut out = String::new();
        for _ in 0..lines {
            let words = self.rng.gen_range(0..=12);
            out.push_str(&self.word_text(words));
            out.push_str(self.pick(&["\r\n", "\r\n", "\n", "\r", ""]));
        }
        out.into_bytes()
    }

    fn frag_unicode(&mut self) -> Vec<u8> {
        let n = self.rng.gen_range(1..=64);
        let mut out = vec![];
        for _ in 0..n {
            if self.chance(0.3) {
                out.extend_from_slice(self.pick(INVALID_UTF8));
            } else {
                out.extend_from_slice(self.pick(UNICODE).as_bytes());
            }
        }
        out
    }

    fn frag_storm(&mut self) -> (Vec<u8>, &'static str) {
        let cap = self.remaining().clamp(1, 20_000);
        let n = self.rng.gen_range(1..=cap);
        match self.rng.gen_range(0..7) {
            0 => {
                let unit = self.pick(&["x", "\u{4e2d}", "\u{1f44d}", "e\u{301}", "\t"]);
                (
                    unit.repeat(n / unit.len().max(1) + 1).into_bytes(),
                    "long-line",
                )
            }
            1 => (b"\n".repeat(n), "linefeed-storm"),
            2 => {
                let mut s = String::new();
                for i in 0..(n / 8 + 1) {
                    let _ = write!(s, "line {i}\r\n");
                }
                (s.into_bytes(), "numbered-lines")
            }
            3 => {
                let mut s = String::from("e");
                s.push_str(&"\u{301}".repeat(n / 2 + 1));
                (s.into_bytes(), "combining-storm")
            }
            4 => (b"\x08".repeat(n), "backspace-storm"),
            5 => (b"\x00".repeat(n), "nul-storm"),
            _ => (b"\x1bM".repeat(n / 2 + 1), "reverse-index-storm"),
        }
    }

    fn frag_csi_random(&mut self) -> Vec<u8> {
        let mut s: Vec<u8> = if self.chance(0.9) {
            b"\x1b[".to_vec()
        } else {
            vec![0x9b]
        };
        if self.chance(0.3) {
            s.push(self.pick(b"?><="));
        }
        let nparams = match self.rng.gen_range(0..100) {
            0..=9 => 0,
            10..=79 => self.rng.gen_range(1..=4),
            80..=94 => self.rng.gen_range(5..=40),
            _ => self.rng.gen_range(200..=1000),
        };
        for i in 0..nparams {
            if i > 0 {
                s.push(if self.chance(0.9) { b';' } else { b':' });
            }
            let n = self.num();
            s.extend_from_slice(n.as_bytes());
        }
        if self.chance(0.15) {
            for _ in 0..self.rng.gen_range(1..=3) {
                s.push(self.pick(b" !\"#$%&'()*+,-./"));
            }
        }
        s.push(self.rng.gen_range(0x40..=0x7e));
        s
    }

    fn frag_csi_targeted(&mut self) -> Vec<u8> {
        let n = self.num();
        let m = self.num();
        let k = self.small_num();
        let s = match self.rng.gen_range(0..40) {
            0 => format!("\x1b[{n};{m}H"),
            1 => format!("\x1b[{n};{m}f"),
            2 => format!("\x1b[{n}d"),
            3 => format!("\x1b[{n}G"),
            4 => format!("\x1b[{n}A"),
            5 => format!("\x1b[{n}B"),
            6 => format!("\x1b[{n}C"),
            7 => format!("\x1b[{n}D"),
            8 => format!("\x1b[{n}E"),
            9 => format!("\x1b[{n}F"),
            10 => format!("\x1b[{n};{m}r"),
            11 => "\x1b[r".to_owned(),
            12 => format!("\x1b[{m};{k}r"),
            13 => format!("\x1b[{n}L"),
            14 => format!("\x1b[{n}M"),
            15 => format!("\x1b[{n}@"),
            16 => format!("\x1b[{n}P"),
            17 => format!("\x1b[{n}X"),
            18 => format!("x\x1b[{n}b"),
            19 => format!("\x1b[{n}S"),
            20 => format!("\x1b[{n}T"),
            21 => format!("\x1b[{n}I"),
            22 => format!("\x1b[{n}Z"),
            23 => self
                .pick(&["\x1b[g", "\x1b[3g", "\x1bH", "\x1b[0g"])
                .to_owned(),
            24 => format!("\x1b[{}J", self.rng.gen_range(0..=4)),
            25 => format!("\x1b[{}K", self.rng.gen_range(0..=3)),
            26 => self.pick(&["\x1b#8", "\x1bc", "\x1b[!p"]).to_owned(),
            27 => self
                .pick(&[
                    "\x1b[6n", "\x1b[5n", "\x1b[c", "\x1b[>c", "\x1b[=c", "\x1b[>q", "\x1bZ",
                ])
                .to_owned(),
            28 => format!("\x1b[{n}t"),
            29 => format!("\x1b[{k} q"),
            30 => "\x1b[?2026$p".to_owned(),
            31 => self
                .pick(&["\x1b[s", "\x1b[u", "\x1b7", "\x1b8"])
                .to_owned(),
            32 => format!("\x1b[38;2;{n};{m};{k}m"),
            33 => format!("\x1b[38:2::{n}:{m}:{k}m"),
            34 => format!("\x1b[48;5;{n}m"),
            35 => format!("\x1b[58;2;{n};{m};{k};4:3;9;53;{n}m"),
            36 => format!("\x1b[{n};{m};{k}m"),
            37 => format!("\x1b[{n};{m}H\x1b[{k}@\x1b[{n}P\x1b[{m}X"),
            38 => format!("\x1b[{k};{n}r\x1b[?6h\x1b[{n};{m}H\x1b[{m}L\x1b[?6l"),
            _ => format!("\x1b[{n}{}", self.pick(&["`", "a", "e", "j", "k"])),
        };
        s.into_bytes()
    }

    fn frag_modes(&mut self) -> Vec<u8> {
        let n = self.small_num();
        let m = self.small_num();
        match self.rng.gen_range(0..12) {
            0..=3 => {
                let mode = if self.chance(0.9) {
                    self.pick(MODES)
                } else {
                    self.rng.gen_range(0..=70_000)
                };
                let set = if self.chance(0.5) { 'h' } else { 'l' };
                let private = if self.chance(0.85) { "?" } else { "" };
                format!("\x1b[{private}{mode}{set}").into_bytes()
            }
            4 => {
                // Alt screen round trip with content inside.
                let enter = self.pick(&["\x1b[?1049h", "\x1b[?47h", "\x1b[?1047h"]);
                let leave = self.pick(&["\x1b[?1049l", "\x1b[?47l", "\x1b[?1047l", ""]);
                let body = self.word_text(10);
                format!("{enter}\x1b[2J\x1b[H{body}\x1b[{n};{m}H{body}{leave}").into_bytes()
            }
            5 => format!("\x1b[>{n}u").into_bytes(),
            6 => format!("\x1b[<{n}u").into_bytes(),
            7 => format!("\x1b[={n};{m}u").into_bytes(),
            8 => b"\x1b[?u".to_vec(),
            9 => {
                // Push far beyond any stack limit, then pop more than pushed.
                let pushes = self.rng.gen_range(1..=600);
                let mut s = "\x1b[>1u".repeat(pushes);
                s.push_str(&format!("\x1b[<{}u", self.num()));
                s.into_bytes()
            }
            10 => {
                // Synchronized output, sometimes never closed.
                let body = self.word_text(20);
                let close = if self.chance(0.7) { "\x1b[?2026l" } else { "" };
                format!("\x1b[?2026h{body}\x1b[?2026h{body}{close}").into_bytes()
            }
            _ => {
                let body = self.word_text(5);
                format!("\x1b[?2004h\x1b[200~{body}\x1b[201~\x1b[?2004l").into_bytes()
            }
        }
    }

    fn frag_esc(&mut self) -> Vec<u8> {
        let n = self.rng.gen_range(1..=8);
        let mut out = vec![];
        for _ in 0..n {
            out.extend_from_slice(
                self.pick(&[
                    "\x1b7",
                    "\x1b8",
                    "\x1bD",
                    "\x1bE",
                    "\x1bH",
                    "\x1bM",
                    "\x1bc",
                    "\x1b(0",
                    "\x1b(B",
                    "\x1b)0",
                    "\x1b*0",
                    "\x1b+B",
                    "\x1b(",
                    "\x1b#8",
                    "\x1b=",
                    "\x1b>",
                    "\x0e",
                    "\x0f",
                    "\x1bZ",
                    "\x1b\\",
                    "\x1b",
                    "\x1bN",
                    "\x1bO",
                    "\x1b%G",
                    "lqqk\x0e",
                    "\x1b(0lqqk\x1b(B",
                ])
                .as_bytes(),
            );
        }
        out
    }

    fn osc_payload(&mut self, num: &str) -> String {
        let n = self.small_num();
        match num {
            "0" | "1" | "2" => {
                let words = self.rng.gen_range(0..=20);
                self.word_text(words)
            }
            "4" => self
                .pick(&[
                    "{n};rgb:ff/00/aa",
                    "{n};#fff",
                    "{n};?",
                    "{n};rgb:ffff/0/0;{n};#000000",
                    "{n}",
                    "x;y",
                ])
                .replace("{n}", &n),
            "7" => {
                let path = self.word_text(3).replace(' ', "/");
                self.pick(&[
                    "file://host/{p}",
                    "file:///{p}",
                    "file://",
                    "file:///%",
                    "file:///%zz%41",
                    "file://h/%2F%00%ff",
                    "http://x/{p}",
                    "{p}",
                    "file:///a;b;c",
                ])
                .replace("{p}", &path)
            }
            "8" => {
                let uri = self.pick(&[
                    "https://example.com/{n}",
                    "file:///tmp/{n}",
                    "",
                    "javascript:alert(1)",
                    "https://\u{1f44d}.example/\u{0}",
                ]);
                let params = self.pick(&["", "id=1", "id=x:y=z", "a=b:c", ";", "id="]);
                let mut s = format!("{params};{}", uri.replace("{n}", &n));
                if self.chance(0.1) {
                    s.push_str(&"a".repeat(self.rng.gen_range(1000..=10_000)));
                }
                s
            }
            "9" => self
                .pick(&["hello", "4;1;50", "4;3", "9;/tmp", "", "  "])
                .to_owned(),
            "10" | "11" | "12" => self
                .pick(&[
                    "?",
                    "rgb:1/2/3",
                    "#123456",
                    "?;?;?",
                    "bogus",
                    "rgb:zz/zz/zz",
                ])
                .to_owned(),
            "50" => self
                .pick(&["CursorShape=1", "CursorShape=", "CursorShape=9", "x"])
                .to_owned(),
            "52" => {
                let data = self.b64(512);
                self.pick(&[
                    "c;{d}",
                    "c;?",
                    "p;{d}",
                    "s0;{d}",
                    ";{d}",
                    "c;!!!notbase64",
                    "c",
                ])
                .replace("{d}", &data)
            }
            "104" => self.pick(&["", "1;2;300", "-1", "x"]).to_owned(),
            "133" => self
                .pick(&[
                    "A",
                    "B",
                    "C",
                    "D",
                    "D;0",
                    "D;130",
                    "D;x",
                    "P;k=i",
                    "A;aid=1;cl=m",
                    "L",
                    "N",
                    "",
                    "Z;;;",
                ])
                .to_owned(),
            "633" => self
                .pick(&[
                    "A",
                    "B",
                    "C",
                    "D",
                    "D;1",
                    "E;ls -la",
                    "E;\\x3b",
                    "P;Cwd=/tmp",
                    "P;IsWindows=True",
                    "",
                ])
                .to_owned(),
            "777" => self
                .pick(&["notify;title;body", "notify;;", "notify", "notify;t;b;c"])
                .to_owned(),
            "9277" => self.pick(&["A", "B", "", "C"]).to_owned(),
            "9278" => self
                .pick(&["d;zz", "d;", "d", "f;{", "k;B;x;y", "k;C", "k", "q", ""])
                .to_owned(),
            "9280" => self
                .pick(&[
                    "A;bash",
                    "A;zsh",
                    "A;bogus",
                    "B",
                    "C;payload",
                    "D?description;text",
                    "D?bogus;x",
                    "D?",
                    "P",
                    "",
                ])
                .to_owned(),
            _ => self.word_text(5),
        }
    }

    fn frag_osc(&mut self) -> Vec<u8> {
        let num = if self.chance(0.9) {
            self.pick(&[
                "0", "1", "2", "4", "7", "8", "9", "10", "11", "12", "50", "52", "104", "110",
                "111", "112", "133", "633", "777", "9277", "9278", "9279", "9280", "781378", "",
            ])
            .to_owned()
        } else {
            self.num()
        };
        let payload = self.osc_payload(&num);
        let mut s = b"\x1b]".to_vec();
        s.extend_from_slice(num.as_bytes());
        if !payload.is_empty() || self.chance(0.5) {
            s.push(b';');
            s.extend_from_slice(payload.as_bytes());
        }
        s.extend_from_slice(self.terminator());
        s
    }

    fn session_id_value(&mut self) -> Option<Value> {
        match self.rng.gen_range(0..100) {
            0..=84 => Some(json!(SESSION_ID)),
            85..=88 => None,
            89..=91 => Some(json!(999)),
            92..=93 => Some(json!(-1)),
            94..=95 => Some(json!("123")),
            96..=97 => Some(json!(u64::MAX)),
            _ => Some(json!(1.5)),
        }
    }

    fn hook_json(&mut self) -> (Value, &'static str) {
        let exit = self.exit_code();
        let exit: Value = if self.chance(0.03) {
            json!(4_294_967_296u64)
        } else {
            json!(exit)
        };
        let block_id = self.new_block_id();
        let pwd = self.pick(&["/tmp", "/", "~", "", "/a b/\u{1f44d}", "C:\\Users\\x"]);
        let mut ps1 = self.word_text(3).into_bytes();
        if self.chance(0.5) {
            let csi = self.frag_csi_targeted();
            ps1.extend(csi);
        }
        let ps1 = if self.chance(0.85) {
            hex::encode(&ps1)
        } else {
            String::from_utf8_lossy(&ps1).into_owned()
        };
        let honor_ps1 = self.chance(0.3);
        let (mut value, kind) = match self.rng.gen_range(0..100) {
            0..=24 => (
                json!({"hook": "Precmd", "value": {
                    "exit_code": exit, "next_block_id": block_id, "pwd": pwd, "ps1": ps1,
                    "honor_ps1": honor_ps1, "rprompt": "\u{1f44d}", "git_branch": "main",
                }}),
                "hook-precmd",
            ),
            25..=34 => (
                json!({"hook": "Precmd", "value": {"pwd": pwd, "ps1": ps1, "honor_ps1": honor_ps1}}),
                "hook-precmd-prompt-only",
            ),
            35..=54 => (
                json!({"hook": "Preexec", "value": {"command": self.word_text(3)}}),
                "hook-preexec",
            ),
            55..=72 => (
                json!({"hook": "CommandFinished", "value": {
                    "exit_code": exit, "next_block_id": block_id,
                }}),
                "hook-command-finished",
            ),
            73..=79 => (
                json!({"hook": "InitShell", "value": {
                    "shell": self.pick(&["zsh", "bash", "fish", "pwsh", "nu", "", "\u{1f44d}"]),
                    "user": "u", "hostname": "h", "is_subshell": self.chance(0.3),
                }}),
                "hook-init-shell",
            ),
            80..=85 => (json!({"hook": "Clear", "value": {}}), "hook-clear"),
            86..=89 => (
                json!({"hook": "InputBuffer", "value": {"buffer": self.word_text(4)}}),
                "hook-input-buffer",
            ),
            90..=93 => (
                json!({"hook": "Bootstrapped", "value": {
                    "histfile": "", "shell": "zsh", "home_dir": "/home/u", "path": "/bin",
                    "aliases": "", "abbreviations": "", "function_names": "",
                    "env_var_names": "", "builtins": "", "keywords": "", "shell_version": "5.9",
                }}),
                "hook-bootstrapped",
            ),
            94..=96 => (json!({"hook": "ExitShell", "value": {}}), "hook-exit-shell"),
            _ => (
                json!({"hook": "NoSuchHook", "value": {"x": 1}}),
                "hook-unknown",
            ),
        };
        if let Some(session_id) = self.session_id_value() {
            if let Some(object) = value.get_mut("value").and_then(Value::as_object_mut) {
                object.insert("session_id".to_owned(), session_id);
            }
        }
        (value, kind)
    }

    fn corrupt(&mut self, bytes: &mut Vec<u8>) {
        if bytes.is_empty() {
            bytes.push(b'{');
            return;
        }
        match self.rng.gen_range(0..6) {
            0 => {
                let at = self.rng.gen_range(0..bytes.len());
                bytes.truncate(at);
            }
            1 => {
                let at = self.rng.gen_range(0..bytes.len());
                bytes[at] = self.rng.gen_range(0..=255);
            }
            2 => {
                let at = self.rng.gen_range(0..=bytes.len());
                let junk_len = self.rng.gen_range(1..=16);
                let junk = self.random_bytes(junk_len);
                bytes.splice(at..at, junk);
            }
            3 => {
                let start = self.rng.gen_range(0..bytes.len());
                let end = self.rng.gen_range(start..=bytes.len());
                let slice = bytes[start..end].to_vec();
                bytes.splice(start..start, slice);
            }
            4 => {
                let depth = self.rng.gen_range(100..=5000);
                let mut nested = "[".repeat(depth).into_bytes();
                nested.extend("]".repeat(depth).into_bytes());
                *bytes = nested;
            }
            _ => {
                for b in bytes.iter_mut() {
                    if b.is_ascii_digit() {
                        *b = b'9';
                    }
                }
            }
        }
    }

    fn frag_warp_hook(&mut self) -> (Vec<u8>, String) {
        if self.chance(0.1) {
            return self.frag_kv_hook();
        }
        let (value, kind) = self.hook_json();
        let mut json = value.to_string().into_bytes();
        let corrupted = self.chance(0.3);
        if corrupted {
            self.corrupt(&mut json);
        }
        let framing = self.rng.gen_range(0..10);
        let mut out = vec![];
        let label;
        match framing {
            0..=5 => {
                let mut hex = hex::encode(&json).into_bytes();
                if self.chance(0.1) {
                    self.corrupt(&mut hex);
                }
                out.extend_from_slice(b"\x1bP$d");
                out.extend(hex);
                out.extend_from_slice(self.pick(&[
                    b"\x9c" as &[u8],
                    b"\x9c",
                    b"\x9c",
                    b"\x1b\\",
                    b"",
                ]));
                label = "dcs-hex";
            }
            6..=7 => {
                out.extend_from_slice(b"\x1b]9278;d;");
                out.extend(hex::encode(&json).into_bytes());
                out.push(0x07);
                label = "osc-hex";
            }
            _ => {
                out.extend_from_slice(b"\x1bP$f");
                out.extend(json);
                out.push(0x9c);
                label = "dcs-unencoded";
            }
        }
        let suffix = if corrupted { "-corrupt" } else { "" };
        (out, format!("{kind}-{label}{suffix}"))
    }

    fn frag_kv_hook(&mut self) -> (Vec<u8>, String) {
        let hook = self.pick(&[
            "InitShell",
            "Precmd",
            "Preexec",
            "CommandFinished",
            "Clear",
            "Bogus",
        ]);
        let mut s = format!("\x1b]9278;k;A;{hook}\x07");
        for _ in 0..self.rng.gen_range(0..=8) {
            let key = self.pick(&[
                "session_id",
                "shell",
                "user",
                "hostname",
                "pwd",
                "exit_code",
                "next_block_id",
                "command",
                "bogus",
            ]);
            let value = match key {
                "session_id" => self.pick(&["123", "123", "999", "x", ""]).to_owned(),
                "exit_code" => self.exit_code().to_string(),
                "next_block_id" => self.new_block_id(),
                _ => self.word_text(2).replace(';', "\\;"),
            };
            let _ = write!(s, "\x1b]9278;k;B;{key};{value}\x07");
        }
        if self.chance(0.85) {
            s.push_str("\x1b]9278;k;C\x07");
        }
        (s.into_bytes(), format!("hook-kv-{hook}"))
    }

    fn frag_dcs(&mut self) -> (Vec<u8>, &'static str) {
        match self.rng.gen_range(0..5) {
            0 => {
                // Sixel (not supported; exercises generic DCS passthrough).
                let mut s = format!(
                    "\x1bP{};1;0q\"1;1;{};{}",
                    self.small_num(),
                    self.num(),
                    self.num()
                );
                for _ in 0..self.rng.gen_range(1..=64) {
                    let piece = match self.rng.gen_range(0..5) {
                        0 => format!(
                            "#{};2;{};{};{}",
                            self.small_num(),
                            self.small_num(),
                            self.small_num(),
                            self.small_num()
                        ),
                        1 => format!("!{}~", self.num()),
                        2 => "$".to_owned(),
                        3 => "-".to_owned(),
                        _ => "??@@~~".to_owned(),
                    };
                    s.push_str(&piece);
                }
                let mut out = s.into_bytes();
                out.extend_from_slice(self.terminator());
                (out, "dcs-sixel")
            }
            1 => (
                self.pick(&[
                    "\x1bP+q544e\x1b\\",
                    "\x1bP$qm\x1b\\",
                    "\x1bP$q r\x1b\\",
                    "\x1bP=1s\x1b\\",
                    "\x1bP=2s\x1b\\",
                    "\x1bP>|x\x1b\\",
                ])
                .as_bytes()
                .to_vec(),
                "dcs-query",
            ),
            _ => {
                let mut s = b"\x1bP".to_vec();
                for i in 0..self.rng.gen_range(0..=4) {
                    if i > 0 {
                        s.push(b';');
                    }
                    s.extend(self.num().into_bytes());
                }
                if self.chance(0.3) {
                    s.push(self.pick(b" !\"#$%&'()*+,-./"));
                }
                s.push(self.rng.gen_range(0x40..=0x7e));
                let len = self.rng.gen_range(0..=512);
                s.extend(self.random_bytes(len));
                s.extend_from_slice(self.terminator());
                (s, "dcs-random")
            }
        }
    }

    fn image_dim(&mut self) -> String {
        if self.cfg.huge_images && self.chance(0.2) {
            self.pick(&["65535", "4294967295", "99999999", "2147483648"])
                .to_owned()
        } else if self.chance(0.7) {
            self.rng.gen_range(0..=64u32).to_string()
        } else {
            self.rng.gen_range(0..=4096u32).to_string()
        }
    }

    fn frag_kitty(&mut self) -> Vec<u8> {
        let mut keys = vec![];
        let action = self.pick(&["t", "T", "p", "d", "q", "a", "f", "c", "", "z"]);
        if !action.is_empty() {
            keys.push(format!("a={action}"));
        }
        let format = self.pick(&["24", "32", "100", "0", "999", ""]);
        if !format.is_empty() {
            keys.push(format!("f={format}"));
        }
        let (w, h) = if self.chance(0.4) {
            let w = self.rng.gen_range(1..=16usize);
            let h = self.rng.gen_range(1..=16usize);
            (w.to_string(), h.to_string())
        } else {
            (self.image_dim(), self.image_dim())
        };
        keys.push(format!("s={w}"));
        keys.push(format!("v={h}"));
        for (key, p) in [
            ("i", 0.7),
            ("p", 0.3),
            ("q", 0.3),
            ("t", 0.2),
            ("o", 0.05),
            ("c", 0.2),
            ("r", 0.2),
            ("x", 0.1),
            ("y", 0.1),
            ("X", 0.1),
            ("Y", 0.1),
            ("z", 0.1),
            ("C", 0.1),
            ("U", 0.05),
            ("d", 0.1),
            ("S", 0.05),
            ("O", 0.05),
        ] {
            if self.chance(p) {
                let value = match key {
                    "t" => self.pick(&["d", "f", "t", "s", "x"]).to_owned(),
                    "o" => "z".to_owned(),
                    "d" => self.pick(&["a", "A", "i", "I", "p", "c", "x"]).to_owned(),
                    "q" => self.pick(&["0", "1", "2", "9"]).to_owned(),
                    _ => self.num(),
                };
                keys.push(format!("{key}={value}"));
            }
        }
        let payload = match self.rng.gen_range(0..4) {
            0 => {
                // Plausibly valid RGBA/RGB data for small dimensions.
                let wn = w.parse::<usize>().unwrap_or(1).min(16);
                let hn = h.parse::<usize>().unwrap_or(1).min(16);
                let bytes = self.random_bytes(wn * hn * 4);
                base64::engine::general_purpose::STANDARD.encode(bytes)
            }
            1 => self.b64(256),
            2 => {
                let mut png = b"\x89PNG\r\n\x1a\n".to_vec();
                let extra = self.rng.gen_range(0..=128);
                png.extend(self.random_bytes(extra));
                base64::engine::general_purpose::STANDARD.encode(png)
            }
            _ => "!!not*base64==".to_owned(),
        };
        let mut s = String::new();
        let chunks = if self.chance(0.2) {
            self.rng.gen_range(2..=5)
        } else {
            1
        };
        for i in 0..chunks {
            let more = if i + 1 < chunks || self.chance(0.05) {
                1
            } else {
                0
            };
            let head = if i == 0 {
                keys.join(",")
            } else {
                String::new()
            };
            let sep = if head.is_empty() { "" } else { "," };
            let _ = write!(s, "\x1b_G{head}{sep}m={more};{payload}\x1b\\");
        }
        let mut out = s.into_bytes();
        if self.chance(0.1) {
            let at = self.rng.gen_range(0..out.len());
            out.truncate(at);
        }
        out
    }

    fn frag_iterm(&mut self) -> Vec<u8> {
        let name = self.b64(16);
        let dims = [
            "auto", "1", "10", "100%", "50px", "0", "-5", "x", "", "200%",
        ];
        let width = if self.cfg.huge_images && self.chance(0.1) {
            "99999999".to_owned()
        } else {
            self.pick(&dims).to_owned()
        };
        let height = self.pick(&dims).to_owned();
        let data = match self.rng.gen_range(0..3) {
            0 => self.b64(512),
            1 => {
                let mut png = b"\x89PNG\r\n\x1a\n\0\0\0\rIHDR".to_vec();
                png.extend(self.random_bytes(64));
                base64::engine::general_purpose::STANDARD.encode(png)
            }
            _ => "%%%not-base64%%%".to_owned(),
        };
        let size = self.num();
        let inline = self.pick(&["0", "1", "1", "x"]);
        let aspect = self.pick(&["0", "1"]);
        let mut s = if self.chance(0.7) {
            format!(
                "\x1b]1337;File=name={name};size={size};width={width};height={height};preserveAspectRatio={aspect};inline={inline}:{data}\x07"
            )
        } else {
            let mut s = format!(
                "\x1b]1337;MultipartFile=name={name};size={size};width={width};height={height};inline={inline}\x07"
            );
            for _ in 0..self.rng.gen_range(0..=4) {
                let part = self.b64(128);
                let _ = write!(s, "\x1b]1337;FilePart={part}\x07");
            }
            if self.chance(0.8) {
                s.push_str("\x1b]1337;FileEnd\x07");
            }
            s
        };
        if self.chance(0.1) {
            s.push_str("\x1b]1337;FileEnd\x07\x1b]1337;FilePart=AAAA\x07");
        }
        s.into_bytes()
    }

    fn frag_apc_pm_sos(&mut self) -> Vec<u8> {
        let intro = self.pick(&[
            b"\x1b_" as &[u8],
            b"\x1b^",
            b"\x1bX",
            b"\x9f",
            b"\x9e",
            b"\x98",
        ]);
        let mut out = intro.to_vec();
        let len = self.rng.gen_range(0..=256);
        out.extend(self.random_bytes(len));
        out.extend_from_slice(self.terminator());
        out
    }

    fn frag_tmux(&mut self) -> Vec<u8> {
        let mut s = String::from("\x1bP1000p");
        for _ in 0..self.rng.gen_range(0..=12) {
            let line = match self.rng.gen_range(0..9) {
                0 => format!("%begin {} {} 0", self.num(), self.num()),
                1 => format!("%end {} {} 0", self.num(), self.num()),
                2 => format!("%error {} {} 0", self.num(), self.num()),
                3 => format!(
                    "%output %{} {}\\033[31m\\015\\012",
                    self.small_num(),
                    self.word_text(3)
                ),
                4 => format!("%window-add @{}", self.small_num()),
                5 => format!(
                    "%layout-change @{} abcd,80x24,0,0,{}",
                    self.small_num(),
                    self.small_num()
                ),
                6 => format!("%session-changed ${} s", self.small_num()),
                7 => "%exit".to_owned(),
                _ => self.word_text(3),
            };
            s.push_str(&line);
            s.push('\n');
        }
        if self.chance(0.5) {
            s.push_str("%exit\n");
        }
        if self.chance(0.5) {
            s.push_str("\x1b\\");
        }
        s.into_bytes()
    }

    fn frag_giant(&mut self) -> Vec<u8> {
        let cap = self.remaining().max(1024);
        let len = self.rng.gen_range(1024..=cap.max(1025));
        let body: String = if self.chance(0.5) {
            "A".repeat(len)
        } else {
            self.word_text(len / 6 + 1)
        };
        let s = match self.rng.gen_range(0..6) {
            0 => format!("\x1b]2;{body}\x07"),
            1 => format!(
                "\x1b]52;c;{}\x07",
                base64::engine::general_purpose::STANDARD.encode(&body)
            ),
            2 => {
                let mut out = b"\x1bP$d".to_vec();
                out.extend(hex::encode(&body).into_bytes());
                out.push(0x9c);
                return out;
            }
            3 => format!("\x1b_G{body}\x1b\\"),
            4 => format!("\x1b]8;;https://x/{body}\x07link\x1b]8;;\x07"),
            _ => format!("\x1b]0;{body}"),
        };
        s.into_bytes()
    }

    /// Generates one fragment of pty output and its descriptive kind.
    fn fragment(&mut self) -> (Vec<u8>, String) {
        let roll = self.rng.gen_range(0..100);
        match roll {
            0..=7 => (self.frag_raw(), "raw-bytes".to_owned()),
            8..=15 => (self.frag_escape_soup(), "escape-soup".to_owned()),
            16..=27 => (self.frag_text(), "text".to_owned()),
            28..=33 => (self.frag_unicode(), "unicode-and-invalid-utf8".to_owned()),
            34..=45 => (self.frag_csi_random(), "csi-random".to_owned()),
            46..=57 => (self.frag_csi_targeted(), "csi-targeted".to_owned()),
            58..=65 => (self.frag_osc(), "osc".to_owned()),
            66..=74 => self.frag_warp_hook(),
            75..=77 => {
                let (bytes, kind) = self.frag_dcs();
                (bytes, kind.to_owned())
            }
            78..=80 => (self.frag_kitty(), "kitty-graphics".to_owned()),
            81..=82 => (self.frag_iterm(), "iterm-image".to_owned()),
            83 => (self.frag_apc_pm_sos(), "apc-pm-sos".to_owned()),
            84..=86 => (self.frag_esc(), "esc".to_owned()),
            87..=88 if self.flags.tmux_control_mode => {
                (self.frag_tmux(), "tmux-control-mode".to_owned())
            }
            87..=91 => {
                let (bytes, kind) = self.frag_storm();
                (bytes, kind.to_owned())
            }
            92..=97 => (self.frag_modes(), "modes".to_owned()),
            _ => (self.frag_giant(), "giant-payload".to_owned()),
        }
    }

    // -- model ops --------------------------------------------------------

    fn size(&mut self) -> (usize, usize) {
        match self.rng.gen_range(0..10) {
            0 => (1, 1),
            1 => (300, 1000),
            2 => (self.rng.gen_range(1..=3), self.rng.gen_range(1..=3)),
            3 => (24, 80),
            4 => (self.rng.gen_range(1..=5), self.rng.gen_range(100..=400)),
            5 => (self.rng.gen_range(100..=300), self.rng.gen_range(1..=5)),
            _ => (self.rng.gen_range(1..=60), self.rng.gen_range(2..=200)),
        }
    }

    fn find_op(&mut self) -> Op {
        let regex = self.chance(0.5);
        let query = match self.rng.gen_range(0..3) {
            0 => self.pick(REGEXES).to_owned(),
            1 => self.pick(WORDS).to_owned(),
            _ => self.pick(UNICODE).to_owned(),
        };
        Op::Find {
            query,
            regex,
            case_sensitive: self.chance(0.3),
        }
    }

    fn model_op(&mut self) -> Op {
        match self.rng.gen_range(0..100) {
            0..=29 => {
                let (rows, cols) = self.size();
                Op::Resize { rows, cols }
            }
            30..=37 => Op::FinishSync,
            38..=41 => Op::ResetProcessor,
            42..=51 => Op::StartCommand,
            52..=59 => Op::Preexec(self.word_text(3)),
            60..=67 => {
                let exit = self.exit_code();
                Op::CommandFinished {
                    exit,
                    block_id: self.new_block_id(),
                }
            }
            68..=75 => {
                let exit = self.exit_code();
                Op::Precmd {
                    exit,
                    block_id: self.new_block_id(),
                }
            }
            76..=79 => Op::PromptOnlyPrecmd,
            80..=84 => Op::ClearHook,
            85..=89 => Op::ClearVisibleScreen,
            90..=95 => self.find_op(),
            _ => Op::Check,
        }
    }

    /// Moves pending stream bytes into `Feed` ops, split per the case's chunk mode.
    fn flush(&mut self) {
        let pending = std::mem::take(&mut self.pending);
        let mut rest = &pending[..];
        while !rest.is_empty() {
            let take = match self.chunk_mode {
                ChunkMode::Whole => rest.len(),
                ChunkMode::SingleByte => 1,
                ChunkMode::UpTo(max) => self.rng.gen_range(1..=max.max(1)).min(rest.len()),
            };
            self.ops.push(Op::Feed(rest[..take].to_vec()));
            self.flushed += take;
            rest = &rest[take..];
        }
    }
}

fn generate_case(cfg: &Config, index: u64) -> Case {
    let mut rng = StdRng::seed_from_u64(case_seed(cfg.seed, index));
    let flags = Flags {
        kitty_images: rng.gen_bool(0.8),
        osc_hyperlinks: rng.gen_bool(0.8),
        tmux_control_mode: rng.gen_bool(0.1),
    };
    let target_len = match rng.gen_range(0..10) {
        0..=5 => rng.gen_range(16..=2048),
        6..=8 => rng.gen_range(2048..=16 * 1024),
        _ => cfg.max_len,
    }
    .clamp(1, cfg.max_len);
    let chunk_mode = match rng.gen_range(0..100) {
        0..=24 => ChunkMode::Whole,
        25..=29 if target_len <= 8 * 1024 => ChunkMode::SingleByte,
        25..=44 => ChunkMode::UpTo(16),
        45..=79 => ChunkMode::UpTo(512),
        _ => ChunkMode::UpTo(8192),
    };
    let mut g = Gen {
        rng,
        cfg,
        flags,
        target_len,
        chunk_mode,
        pending: vec![],
        flushed: 0,
        ops: vec![],
        fragments: vec![],
        block_ids: vec![],
        next_block: 0,
    };

    if g.chance(0.7) {
        let (rows, cols) = g.size();
        g.ops.push(Op::Resize { rows, cols });
    }
    while g.flushed + g.pending.len() < g.target_len {
        if g.chance(0.12) {
            g.flush();
            let op = g.model_op();
            g.ops.push(op);
            continue;
        }
        let (mut bytes, kind) = g.fragment();
        let room = g.remaining();
        if room == 0 {
            break;
        }
        bytes.truncate(room);
        let offset = g.flushed + g.pending.len();
        g.fragments.push((offset, bytes.len(), kind));
        g.pending.extend(bytes);
    }
    g.flush();
    if g.chance(0.3) {
        let (rows, cols) = g.size();
        g.ops.push(Op::Resize { rows, cols });
    }
    if g.chance(0.3) {
        let op = g.find_op();
        g.ops.push(op);
    }
    Case {
        seed: cfg.seed,
        index,
        flags,
        ops: g.ops,
        fragments: g.fragments,
    }
}

// ---------------------------------------------------------------------------
// Execution and invariants
// ---------------------------------------------------------------------------

fn apply_op(model: &mut TerminalModel, processor: &mut Processor, op: &Op) -> Result<(), String> {
    match op {
        Op::Feed(bytes) => processor.parse_bytes(model, bytes, &mut sink()),
        Op::Resize { rows, cols } => {
            let last = *model.block_list().size();
            model.resize(SizeUpdate::from_cell_dimensions(last, *rows, *cols));
        }
        Op::FinishSync => processor.finish_sync_output(model, &mut sink()),
        Op::ResetProcessor => *processor = Processor::new(),
        Op::StartCommand => {
            let _ = model.start_command_execution();
        }
        Op::Preexec(command) => Handler::preexec(
            model,
            PreexecValue {
                command: command.clone(),
                session_id: Some(SESSION_ID),
            },
        ),
        Op::CommandFinished { exit, block_id } => Handler::command_finished(
            model,
            CommandFinishedValue {
                completion_metadata: CompletionMetadata {
                    exit_code: ExitCode::from(*exit),
                    next_block_id: BlockId::from(block_id.clone()),
                },
                session_id: Some(SESSION_ID),
            },
        ),
        Op::Precmd { exit, block_id } => Handler::precmd_with_completion_metadata(
            model,
            PrecmdValue {
                completion_metadata: CompletionMetadata {
                    exit_code: ExitCode::from(*exit),
                    next_block_id: BlockId::from(block_id.clone()),
                },
                prompt_metadata: PromptMetadata {
                    session_id: Some(SESSION_ID),
                    ..Default::default()
                },
            },
        ),
        Op::PromptOnlyPrecmd => Handler::prompt_only_precmd(
            model,
            PromptMetadata {
                session_id: Some(SESSION_ID),
                ..Default::default()
            },
        ),
        Op::ClearHook => Handler::clear(
            model,
            ClearValue {
                session_id: Some(SESSION_ID),
            },
        ),
        Op::ClearVisibleScreen => model.clear_visible_screen(),
        Op::Find {
            query,
            regex,
            case_sensitive,
        } => run_find(model, query, *regex, *case_sensitive)?,
        Op::Check => check_invariants(model)?,
    }
    Ok(())
}

/// Runs find over every block's prompt/command and output grids and the alt
/// screen -- the same per-grid calls `terminal::find::model::block_list` and
/// `::alt_screen` make -- and checks each match is a forward range.
fn run_find(
    model: &TerminalModel,
    query: &str,
    regex: bool,
    case_sensitive: bool,
) -> Result<(), String> {
    let Ok(dfas) = RegexDFAs::new_with_config(
        query,
        FindConfig {
            is_regex_enabled: regex,
            is_case_sensitive: case_sensitive,
        },
    ) else {
        // An invalid regex is rejected the same way the find bar rejects it.
        return Ok(());
    };
    let check =
        |label: &str, matches: Vec<std::ops::RangeInclusive<Point>>| -> Result<(), String> {
            for range in matches {
                let (start, end) = (range.start(), range.end());
                if (start.row, start.col) > (end.row, end.col) {
                    return Err(format!(
                        "find {query:?}: {label} returned a backwards match {start:?}..={end:?}"
                    ));
                }
            }
            Ok(())
        };
    for (i, block) in model.block_list().blocks().iter().enumerate() {
        check(
            &format!("block {i} prompt/command grid"),
            block.find_prompt_and_command_grid_matches(&dfas),
        )?;
        check(
            &format!("block {i} output grid"),
            block.find_output_grid_matches(&dfas),
        )?;
    }
    check("alt screen", model.alt_screen().find(&dfas))
}

/// Invariants that the code itself relies on (see the report in the commit
/// message for the code that establishes each one).
fn check_invariants(model: &TerminalModel) -> Result<(), String> {
    let block_list = model.block_list();
    let blocks = block_list.blocks();
    // `BlockList::active_block` is `blocks.last().expect("at least one block should exist")`.
    if blocks.is_empty() {
        return Err("block list has no blocks".to_owned());
    }
    // The block-height SumTree holds exactly one `Block` item per block: its
    // `block_count` dimension is used directly as a block index
    // (`cursor.start().block_count` in `BlockList`).
    let summary = block_list.block_heights().summary();
    if summary.block_count != blocks.len() {
        return Err(format!(
            "block_heights has {} Block items but the block list has {} blocks",
            summary.block_count,
            blocks.len()
        ));
    }
    let total = summary.height.as_f64();
    if !total.is_finite() || total < -1e-6 {
        return Err(format!("block_heights total height is {total}"));
    }
    let scope = block_list.transcript_scope();
    for (i, block) in blocks.iter().enumerate() {
        let height = block.height(scope).as_f64();
        if !height.is_finite() || height < -1e-6 {
            return Err(format!("block {i} has height {height}"));
        }
        check_grid(
            &format!("block {i} output grid"),
            block.output_grid().grid_handler(),
            false,
        )?;
    }
    check_grid("alt screen grid", model.alt_screen().grid_handler(), true)
}

fn check_grid(label: &str, grid: &GridHandler, region_within_rows: bool) -> Result<(), String> {
    let total_rows = grid.total_rows();
    let visible_rows = grid.visible_rows();
    let columns = grid.columns();
    // `InitialCursorState::new` (grid/resize.rs) logs "cursor should not be
    // outside the bounds of the grid!" and clamps; every cursor writer
    // (`goto`, `input`, ...) clamps to the visible region.
    let cursor = grid.cursor_point();
    if cursor.row >= total_rows || cursor.col >= columns {
        return Err(format!(
            "{label}: cursor {cursor:?} outside grid ({total_rows} rows, {visible_rows} visible, {columns} columns)"
        ));
    }
    // `set_scrolling_region` rejects top >= bottom and clamps both ends to
    // the visible rows; resize/reset re-derive it from the visible rows.
    let region = grid.scroll_region();
    if region.start > region.end || (region_within_rows && region.end.0 > visible_rows) {
        return Err(format!(
            "{label}: scroll region {:?}..{:?} invalid for {visible_rows} visible rows",
            region.start, region.end
        ));
    }
    // `GridHandler::row` documents that it returns a row for every index
    // within the bounds of the grid; this also exercises flat-storage row
    // reconstruction for every row.
    for row in 0..total_rows {
        if grid.row(row).is_none() {
            return Err(format!(
                "{label}: row {row} of {total_rows} could not be read"
            ));
        }
    }
    Ok(())
}

thread_local! {
    static LAST_PANIC: RefCell<Option<String>> = const { RefCell::new(None) };
    static CURRENT_OP: Cell<Option<usize>> = const { Cell::new(None) };
}

/// Records each panic's message and location for the panicking thread instead
/// of printing it, so the harness can report it against its case.
fn install_panic_hook() {
    let backtrace = env_flag("PHOSPHOR_FUZZ_BACKTRACE", false);
    panic::set_hook(Box::new(move |info| {
        let mut message = info.to_string();
        if backtrace {
            let _ = write!(message, "\n{}", std::backtrace::Backtrace::force_capture());
        }
        // Only case threads report through their outcome; a panic anywhere
        // else (e.g. an executor thread) must stay visible.
        let is_case_thread = std::thread::current()
            .name()
            .is_some_and(|name| name.starts_with("fuzz-case-"));
        if !is_case_thread {
            eprintln!("{message}");
        }
        LAST_PANIC.with(|last| *last.borrow_mut() = Some(message));
    }));
}

fn execute_case(case: &Case) -> Result<(), String> {
    let _kitty = FeatureFlag::KittyImages.override_enabled(case.flags.kitty_images);
    let _links = FeatureFlag::OscHyperlinks.override_enabled(case.flags.osc_hyperlinks);
    let _tmux = FeatureFlag::SSHTmuxWrapper.override_enabled(case.flags.tmux_control_mode);

    let mut model = TerminalModel::mock(None, None);
    let mut processor = Processor::new();
    for (i, op) in case.ops.iter().enumerate() {
        CURRENT_OP.with(|current| current.set(Some(i)));
        apply_op(&mut model, &mut processor, op)
            .map_err(|e| format!("after op #{i} ({}): {e}", op.summary()))?;
    }
    CURRENT_OP.with(|current| current.set(None));
    processor.finish_sync_output(&mut model, &mut sink());
    check_invariants(&model).map_err(|e| format!("end of case: {e}"))
}

enum Outcome {
    Passed(Duration),
    Failed {
        kind: &'static str,
        message: String,
        elapsed: Duration,
    },
    Hung,
}

/// Runs a case on its own thread so a panic is contained and a hang can be
/// detected.
fn run_case(case: Arc<Case>, hang: Duration) -> Outcome {
    let (tx, rx) = mpsc::channel();
    let worker_case = Arc::clone(&case);
    let spawned = std::thread::Builder::new()
        .name(format!("fuzz-case-{}", case.index))
        .spawn(move || {
            let start = Instant::now();
            let result = panic::catch_unwind(AssertUnwindSafe(|| execute_case(&worker_case)));
            let elapsed = start.elapsed();
            let result = match result {
                Ok(Ok(())) => Ok(()),
                Ok(Err(message)) => Err(("invariant", message)),
                Err(payload) => {
                    let recorded = LAST_PANIC.with(|last| last.borrow_mut().take());
                    let mut message = recorded.unwrap_or_else(|| {
                        payload
                            .downcast_ref::<&str>()
                            .map(|s| (*s).to_owned())
                            .or_else(|| payload.downcast_ref::<String>().cloned())
                            .unwrap_or_else(|| "<non-string panic payload>".to_owned())
                    });
                    if let Some(i) = CURRENT_OP.with(Cell::get) {
                        let summary = worker_case.ops.get(i).map(Op::summary).unwrap_or_default();
                        let _ = write!(message, "\n(during op #{i}: {summary})");
                    }
                    Err(("panic", message))
                }
            };
            let _ = tx.send((result, elapsed));
        });
    if let Err(e) = spawned {
        return Outcome::Failed {
            kind: "harness",
            message: format!("could not spawn the case thread: {e}"),
            elapsed: Duration::ZERO,
        };
    }
    match rx.recv_timeout(hang) {
        Ok((Ok(()), elapsed)) => Outcome::Passed(elapsed),
        Ok((Err((kind, message)), elapsed)) => Outcome::Failed {
            kind,
            message,
            elapsed,
        },
        Err(RecvTimeoutError::Timeout) => Outcome::Hung,
        Err(RecvTimeoutError::Disconnected) => Outcome::Failed {
            kind: "panic",
            message: "case thread exited without reporting a result".to_owned(),
            elapsed: Duration::ZERO,
        },
    }
}

fn write_case(dir: &Path, stem: &str, case: &Case, header: &str) -> std::io::Result<PathBuf> {
    std::fs::create_dir_all(dir)?;
    let bin = dir.join(format!("{stem}.bin"));
    let ops = dir.join(format!("{stem}.ops"));
    std::fs::write(&bin, case.stream())?;
    std::fs::write(&ops, case.ops_text(header))?;
    Ok(ops)
}

struct Failure {
    index: u64,
    kind: &'static str,
    message: String,
    path: Option<PathBuf>,
}

#[test]
#[ignore = "long-running randomized fuzz harness; run explicitly, see the module docs"]
fn terminal_fuzz() {
    let cfg = Config::from_env();
    install_panic_hook();
    println!(
        "terminal_fuzz: seed={} iters={} secs={} max_len={} out={}{}",
        cfg.seed,
        cfg.iters,
        cfg.secs,
        cfg.max_len,
        cfg.out_dir.display(),
        cfg.only_case
            .map(|c| format!(" (only case {c})"))
            .unwrap_or_default()
    );

    let indices: Box<dyn Iterator<Item = u64>> = match cfg.only_case {
        Some(index) => Box::new(std::iter::once(index)),
        None => Box::new(0..cfg.iters),
    };
    let budget = Duration::from_secs(cfg.secs);
    let started = Instant::now();
    let mut last_progress = Instant::now();
    let mut failures: Vec<Failure> = vec![];
    let mut ran = 0u64;
    let mut bytes = 0usize;
    let mut hung = false;
    let in_flight_stem = format!("in-flight-{}", cfg.seed);

    for index in indices {
        if cfg.only_case.is_none() && started.elapsed() >= budget {
            println!("terminal_fuzz: wall-clock budget of {}s reached", cfg.secs);
            break;
        }
        let case = Arc::new(generate_case(&cfg, index));
        if cfg.in_flight {
            let header = format!("in flight: seed {} case {index}", cfg.seed);
            let _ = write_case(&cfg.out_dir, &in_flight_stem, &case, &header);
        }
        let outcome = run_case(Arc::clone(&case), cfg.hang);
        ran += 1;
        bytes += case.stream_len();

        let failure = match outcome {
            Outcome::Passed(elapsed) if elapsed > cfg.slow => Some((
                "slow",
                format!(
                    "took {:.2}s for {} stream bytes in {} ops",
                    elapsed.as_secs_f64(),
                    case.stream_len(),
                    case.ops.len()
                ),
            )),
            Outcome::Passed(_) => None,
            Outcome::Failed {
                kind,
                message,
                elapsed,
            } => {
                let slow = if elapsed > cfg.slow {
                    format!(" (also slow: {:.2}s)", elapsed.as_secs_f64())
                } else {
                    String::new()
                };
                Some((kind, format!("{message}{slow}")))
            }
            Outcome::Hung => {
                hung = true;
                Some((
                    "hang",
                    format!(
                        "still running after {}s ({} stream bytes, {} ops); stopping the run",
                        cfg.hang.as_secs(),
                        case.stream_len(),
                        case.ops.len()
                    ),
                ))
            }
        };

        if let Some((kind, message)) = failure {
            let header = format!("seed {} case {index}: {kind}\n{message}", cfg.seed);
            let stem = format!("{}-{index}", cfg.seed);
            let path = match write_case(&cfg.out_dir, &stem, &case, &header) {
                Ok(path) => Some(path),
                Err(e) => {
                    println!("terminal_fuzz: could not dump case {index}: {e}");
                    None
                }
            };
            println!(
                "terminal_fuzz: FAILURE seed={} case={index} kind={kind} dump={}\n  {}",
                cfg.seed,
                path.as_ref()
                    .map(|p| p.display().to_string())
                    .unwrap_or_else(|| "<none>".to_owned()),
                message.replace('\n', "\n  ")
            );
            failures.push(Failure {
                index,
                kind,
                message,
                path,
            });
        }
        if hung {
            break;
        }
        if last_progress.elapsed() >= Duration::from_secs(30) {
            last_progress = Instant::now();
            println!(
                "terminal_fuzz: {ran} cases, {} KiB, {} failures, {:.0}s elapsed",
                bytes / 1024,
                failures.len(),
                started.elapsed().as_secs_f64()
            );
        }
    }

    if cfg.in_flight && !hung {
        let _ = std::fs::remove_file(cfg.out_dir.join(format!("{in_flight_stem}.bin")));
        let _ = std::fs::remove_file(cfg.out_dir.join(format!("{in_flight_stem}.ops")));
    }
    let _ = panic::take_hook();

    println!(
        "terminal_fuzz: done: seed={} cases={ran} bytes={} failures={} elapsed={:.1}s",
        cfg.seed,
        bytes,
        failures.len(),
        started.elapsed().as_secs_f64()
    );
    if !failures.is_empty() {
        let mut report = format!(
            "terminal_fuzz found {} failing case(s) with seed {}:\n",
            failures.len(),
            cfg.seed
        );
        for failure in &failures {
            let first_line = failure.message.lines().next().unwrap_or_default();
            let _ = writeln!(
                report,
                "  seed={} case={} kind={} dump={} :: {first_line}",
                cfg.seed,
                failure.index,
                failure.kind,
                failure
                    .path
                    .as_ref()
                    .map(|p| p.display().to_string())
                    .unwrap_or_else(|| "<none>".to_owned()),
            );
        }
        let _ = writeln!(
            report,
            "reproduce one with PHOSPHOR_FUZZ_SEED={} PHOSPHOR_FUZZ_CASE=<case>, or \
             PHOSPHOR_FUZZ_REPLAY=<dump> and the terminal_fuzz_replay test",
            cfg.seed
        );
        panic!("{report}");
    }
}

#[test]
#[ignore = "replays a case dumped by terminal_fuzz; set PHOSPHOR_FUZZ_REPLAY"]
fn terminal_fuzz_replay() {
    let Ok(path) = std::env::var("PHOSPHOR_FUZZ_REPLAY") else {
        println!("terminal_fuzz_replay: PHOSPHOR_FUZZ_REPLAY is not set; nothing to replay");
        return;
    };
    install_panic_hook();
    let path = PathBuf::from(path);
    let bin = path.with_extension("bin");
    let ops = path.with_extension("ops");
    let stream =
        std::fs::read(&bin).unwrap_or_else(|e| panic!("could not read {}: {e}", bin.display()));
    let case = match std::fs::read_to_string(&ops) {
        Ok(text) => parse_case(&text, &stream)
            .unwrap_or_else(|e| panic!("could not parse {}: {e}", ops.display())),
        // A bare .bin (no op list) is replayed as one pty read.
        Err(_) => Case {
            seed: 0,
            index: 0,
            flags: Flags {
                kitty_images: true,
                osc_hyperlinks: true,
                tmux_control_mode: false,
            },
            ops: vec![Op::Feed(stream)],
            fragments: vec![],
        },
    };
    let hang = Duration::from_secs(env_u64("PHOSPHOR_FUZZ_HANG_SECS").unwrap_or(600).max(1));
    let slow = Duration::from_millis(env_u64("PHOSPHOR_FUZZ_SLOW_MS").unwrap_or(2000));
    println!(
        "terminal_fuzz_replay: {} (seed {} case {}, {} ops, {} stream bytes)",
        path.display(),
        case.seed,
        case.index,
        case.ops.len(),
        case.stream_len()
    );
    let outcome = run_case(Arc::new(case), hang);
    let _ = panic::take_hook();
    match outcome {
        Outcome::Passed(elapsed) if elapsed > slow => {
            panic!("slow: case took {:.2}s", elapsed.as_secs_f64())
        }
        Outcome::Passed(elapsed) => {
            println!(
                "terminal_fuzz_replay: passed in {:.3}s",
                elapsed.as_secs_f64()
            )
        }
        Outcome::Failed { kind, message, .. } => panic!("{kind}: {message}"),
        Outcome::Hung => panic!("hang: still running after {}s", hang.as_secs()),
    }
}
